// El JSON de entrada viene del nodo anterior usando la expresión correcta de n8n
const allSlots = $input.first().json.collection;

// Obtiene la fecha y hora actual de forma robusta
const now = new Date();

// 1. Calcular el inicio del día de mañana en UTC para una comparación precisa
const tomorrowUTC = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + 1));

// Verificamos que allSlots sea un array válido
if (!allSlots || !Array.isArray(allSlots)) {
  return [{ json: { error: "La estructura del JSON de entrada no es la esperada o la colección está vacía." } }];
}

// 2. Filtrar los slots para que sean a partir de mañana (comparando en UTC)
const futureSlots = allSlots.filter(slot => {
  const slotDate = new Date(slot.start_time);
  return slotDate >= tomorrowUTC;
});

// 3. Ordenar y tomar los 3 más próximos
const closestThreeSlots = futureSlots
  .sort((a, b) => new Date(a.start_time) - new Date(b.start_time))
  .slice(0, 3);

// 4. Formatear las fechas a la zona horaria de Puerto Rico
const formatter = new Intl.DateTimeFormat('es-PR', {
  timeZone: 'America/Puerto_Rico',
  year: 'numeric',
  month: 'long',
  day: 'numeric',
  hour: 'numeric',
  minute: 'numeric',
  hour12: true,
});

const formattedSlots = closestThreeSlots.map(slot => {
  const slotDate = new Date(slot.start_time);
  return formatter.format(slotDate);
});

// Devolver el resultado final
return [{
  json: {
    slotsDisponibles: formattedSlots
  }
}];

